"""Explicit local configuration; no fallback to the system PostgreSQL service."""
import os
from pathlib import Path

from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parents[3]
load_dotenv(ROOT / "BancoModeloUse" / ".env.local", override=False)


def _required(name: str) -> str:
    value = os.getenv(name, "").strip()
    if not value:
        raise ValueError(f"Missing required setting: {name}")
    return value


def db_params(domain: str) -> dict:
    """Read only the isolated cluster configuration generated by local_postgres.py."""
    prefix = f"{domain}_DB_"
    params = {
        "host": _required(prefix + "HOST"),
        "port": int(_required(prefix + "PORT")),
        "dbname": _required(prefix + "NAME"),
        "user": _required(prefix + "USER"),
        "password": _required(prefix + "PASSWORD"),
        "connect_timeout": 5,
    }
    if params["host"] != "127.0.0.1" or params["port"] != 5544:
        raise ValueError("Inference only accepts the isolated local PostgreSQL at 127.0.0.1:5544")
    expected = {"INDUSTRIAL": "db_industrial", "FINANCEIRO": "db_financeiro"}[domain]
    if params["dbname"] != expected:
        raise ValueError(f"Unexpected {domain} database")
    return params


def app_db_params() -> dict:
    params = db_params("FINANCEIRO")
    params["dbname"] = "db_inference_app"
    return params


def api_token() -> str:
    return _required("INFERENCE_API_TOKEN")


def vllm_url() -> str:
    value = os.getenv("INFERENCE_VLLM_URL", "").strip().rstrip("/")
    if value and not value.startswith("https://"):
        raise ValueError("INFERENCE_VLLM_URL must use HTTPS")
    return value
